package org.mockito.internal.invocation;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.exceptions.PrintableInvocation;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.invocation.InvocationMatcher;
import org.mockito.internal.matcher.Matcher;
import org.mockito.internal.matchers.CapturesArguments;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.internal.reporting.PrintingFriendlyInvocation;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

public class InvocationMatcher_captureArgumentsFrom_TriageGen0Test {

    // Mocking the CapturesArguments interface/class as it is used in an instanceof check
    public interface CapturesArguments extends Matcher {
        void captureFrom(Object argument);
    }

    @Test
    public void testCaptureArgumentsFrom_AllMatchersAreCapturersAndArgumentsMatch() {
        Invocation invocation = mock(Invocation.class);
        Object arg1 = "first";
        Object arg2 = "second";
        when(invocation.getArguments()).thenReturn(new Object[]{arg1, arg2});

        CapturesArguments capturer1 = mock(CapturesArguments.class);
        CapturesArguments capturer2 = mock(CapturesArguments.class);
        List<Matcher> matchers = Arrays.asList(capturer1, capturer2);

        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);
        invocationMatcher.captureArgumentsFrom(invocation);

        verify(capturer1).captureFrom(arg1);
        verify(capturer2).captureFrom(arg2);
    }

    @Test
    public void testCaptureArgumentsFrom_SomeMatchersAreNotCapturers() {
        Invocation invocation = mock(Invocation.class);
        Object arg1 = "first";
        when(invocation.getArguments()).thenReturn(new Object[]{arg1});

        CapturesArguments capturer1 = mock(CapturesArguments.class);
        Matcher regularMatcher = mock(Matcher.class); // Not an instance of CapturesArguments
        List<Matcher> matchers = Arrays.asList(capturer1, regularMatcher);

        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);
        invocationMatcher.captureArgumentsFrom(invocation);

        verify(capturer1).captureFrom(arg1);
        // regularMatcher should be skipped silently
    }

    @Test
    public void testCaptureArgumentsFrom_FewerArgumentsThanMatchers() {
        Invocation invocation = mock(Invocation.class);
        Object arg1 = "only one";
        // Only 1 argument provided, but 2 matchers exist
        when(invocation.getArguments()).thenReturn(new Object[]{arg1});

        CapturesArguments capturer1 = mock(CapturesArguments.class);
        CapturesArguments capturer2 = mock(CapturesArguments.class);
        List<Matcher> matchers = Arrays.asList(capturer1, capturer2);

        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);
        invocationMatcher.captureArgumentsFrom(invocation);

        verify(capturer1).captureFrom(arg1);
        // capturer2 should not be called because i.getArguments().length (1) is not > k (1)
    }

    @Test
    public void testCaptureArgumentsFrom_EmptyMatchers() {
        Invocation invocation = mock(Invocation.class);
        when(invocation.getArguments()).thenReturn(new Object[]{"arg"});

        List<Matcher> matchers = Collections.emptyList();
        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);

        // Should not throw exception and do nothing
        invocationMatcher.captureArgumentsFrom(invocation);
    }

    @Test
    public void testCaptureArgumentsFrom_EmptyArguments() {
        Invocation invocation = mock(Invocation.class);
        when(invocation.getArguments()).thenReturn(new Object[]{});

        CapturesArguments capturer = mock(CapturesArguments.class);
        List<Matcher> matchers = Collections.singletonList(capturer);

        InvocationMatcher invocationMatcher = new InvocationMatcher(invocation, matchers);
        invocationMatcher.captureArgumentsFrom(invocation);

        // Should not call captureFrom because length (0) is not > k (0)
        verify(capturer, org.mockito.Mockito.never()).captureFrom(org.mockito.ArgumentMatchers.any());
    }

    // Helper to mock invocation behavior in the absence of full Mockito environment setup for internal classes
    private static class MockInvocation extends Invocation {
        private final Object[] args;
        public MockInvocation(Object[] args) { this.args = args; }
        @Override public Object[] getArguments() { return args; }
    }

    // Since we cannot easily use Mockito.when on internal Mockito classes in some environments, 
    // we use a simple stubbing approach if needed, but standard Mockito mock should work for Invocation.
    private static <T> T when(T mock) {
        return mock;
    }
}

// Adding a small helper to handle the static when for the mock
class MockitoHelper {
    public static <T> T when(T mock) {
        return mock;
    }
}
